import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.pT28JT3G.js";const m=JSON.parse('{"title":"The landing site, the web app and the API each have their own hostname and container","description":"","frontmatter":{"status":"accepted","date":"2026-11-06T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname.md","filePath":"docs/adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname.md"}'),o={name:"docs/adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname.md"};function i(h,e,r,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="the-landing-site-the-web-app-and-the-api-each-have-their-own-hostname-and-container" tabindex="-1">The landing site, the web app and the API each have their own hostname and container <a class="header-anchor" href="#the-landing-site-the-web-app-and-the-api-each-have-their-own-hostname-and-container" aria-label="Permalink to &quot;The landing site, the web app and the API each have their own hostname and container&quot;">​</a></h1><p>The server stays an API only, and each part a browser or a developer reaches is its own deliverable in its own container, behind the shared Caddy (<a href="./0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>):</p><table tabindex="0"><thead><tr><th>Hostname</th><th>Serves</th><th>Container</th></tr></thead><tbody><tr><td><code>coach-poulpy.com</code></td><td>The landing site: static pages for search engines and newcomers</td><td>A static file server</td></tr><tr><td><code>app.coach-poulpy.com</code></td><td>The signed-in website (<a href="./../roadmap">phase 4</a>): a Vue single-page app running the shared engine with Kotlin/JS</td><td>A static file server</td></tr><tr><td><code>api.coach-poulpy.com</code></td><td>The API under <code>/api/v1</code>, with its OpenAPI description, OAuth and <code>/.well-known/</code> routes</td><td>The server</td></tr></tbody></table><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li><strong>Different jobs, different rhythms.</strong> The landing site changes with marketing copy and wants pre-rendered pages; the app changes with features and wants strict security headers and the sign-in cookie. Neither release restarts the other or the API.</li><li><strong>A stable address for developers.</strong> <code>api.coach-poulpy.com/api/v1</code> stays the same whatever the websites become.</li><li><strong>The cookie stays first-party.</strong> The three hostnames are one site, so the app&#39;s SameSite cookie is sent to the API; the API answers CORS only for <code>app.coach-poulpy.com</code> (and the landing site if it ever calls it).</li><li><strong>Small cost.</strong> A static file server needs about 15 MB of memory, against the server&#39;s 512 MB.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The landing site and the app are separate builds in <code>web/</code>; the app&#39;s container arrives with phase 4, the landing site&#39;s when it is written.</li><li>Caddy gets one route per hostname, each updated by its own deploy, as the API&#39;s is today.</li><li>The API&#39;s CORS list and the cookie&#39;s settings follow these hostnames; a new website hostname means updating both.</li></ul>',7)])])}const w=t(o,[["render",i]]);export{m as __pageData,w as default};
